/* =========================================================
   F8K® — 挂绳实体卡（React Bits <Lanyard /> 原生 JS 移植，MIT）
   原作：React Bits Lanyard（JavaScript + CSS variant）
   本文件：无 JSX / 无 React / 无 WASM 物理引擎，在原生 DOM + three.js 上复刻同一套行为：
     · 绳索物理：固定环 → j1/j2/j3 三枚绳节（max 距离 1）→ 卡片（spherical 挂点偏移 1.5），
       用 PBD（Position-Based Dynamics）逐迭代投影求解；重力 −40、线性/角阻尼 4、
       卡片质量 ≈ 17 倍绳节（与 Rapier 默认密度下的体质量比一致）；
     · 拖拽：按下卡片 → 卡片变 kinematic 跟随指针（z=0 指针平面，映射与原版一致），
       松手恢复动态并继承拖拽速度（抛掷惯性），绳链被约束拽着走；
     · 系带：屏幕朝向 ribbon（MeshLine 同款思路：切向 × 视线方向求侧向），
       沿 CatmullRom 曲线铺品牌织带贴图，wrap 重复 4 次，depthTest 关（与原版一致）；
     · 卡片：card.glb（React Bits 仓库素材，几何已抽为 base64 内联，零外部请求），
       正面 "let's talk ↗ / 2026"、背面联系方式，均为运行时 canvas 绘制（品牌化落地）；
       挂绳贴图同为 canvas 品牌织带（奶油底 · 克莱因 F8K）。
     性能纪律与其他 canvas 场景一致：接近页脚才初始化、交集进出暂停、后台暂停、
     静止 30fps 隔帧 / 拖拽时 60fps、DPR 上限、prefers-reduced-motion 直接放弃。
   ========================================================= */
(() => {
  'use strict';

  /* ---------- card.glb 几何载荷（React Bits 仓库 src/assets/lanyard/card.glb 抽出） ---------- */
  const GEO = [{"verts":1164,"p":"","n":"","u":"","i":"","it":1},{"verts":1129,"p":"","n":"","u":"","i":"","it":1},{"verts":1721,"p":"","n":"","u":"","i":"","it":1}];

  const stage = document.querySelector('[data-lanyard]');
  const canvas = document.getElementById('lanyardCanvas');
  if (!stage || !canvas) return;
  if (window.matchMedia('(prefers-reduced-motion: reduce)').matches) return;

  const loadScript = (src) => new Promise((resolve, reject) => {
    const s = document.createElement('script');
    s.src = src;
    s.onload = resolve;
    s.onerror = reject;
    document.head.appendChild(s);
  });

  /* 接近页脚才初始化（其它 3D 在 f8k-idle；挂绳在深尾，首次交集前 600px 预取） */
  let started = false;
  const gate = new IntersectionObserver((en) => {
    if (started || !en[0].isIntersecting) return;
    started = true;
    gate.disconnect();
    window.__f8kThree = window.__f8kThree || loadScript('assets/vendor/three.min.js');
    window.__f8kThree.then(init).catch(() => stage.classList.add('is-failed'));
  }, { rootMargin: '600px' });
  gate.observe(stage);

  function init() {
    if (!window.THREE) return;
    const T = window.THREE;
    try {
      /* ================================================================
         常量（与原版 props 默认值一致）
         ================================================================ */
      const GRAVITY = -40;
      const ROPE_LEN = 1;        // useRopeJoint 最大距离
      const HANG_LEN = 1.5;      // useSphericalJoint 挂点偏移 [0,1.5,0]
      const CENTER_Y = -0.35;    // 世界垂直中心（锚点 2.2 → 卡底约 -3.4）
      const FIT_H = 3.5;         // 半高需求（含甩动余量）
      const FIT_W = 2.9;         // 半宽需求（含横向甩动余量）
      const FOV = 20;
      const DAMP = 4;            // 线性/角阻尼 ala angularDamping 4
      const ITER = 12;           // PBD 约束投影迭代
      const C_MASS = 17;         // 卡片质量 ∈ 绳节（Rapier 默认密度下的体质量比）
      const STEP = 1 / 120;      // 物理固定步长
      const CARD_SCALE = 2.25;   // 原版视觉组 scale
      const BAND_WIDTH = 0.34;   // 系带世界宽度（lineWidth 视觉等效）
      const SWING_TWIST = 0.12;  // 摆动角速度 → 扭摆激励系数（挂绳翻面手感）

      const isMobile = /iPad|iPhone|iPod/.test(navigator.userAgent) || window.innerWidth < 768;
      const lowPower = isMobile;

      const doc = document.documentElement;
      const readHex = (k, fb) => {
        const t = getComputedStyle(doc).getPropertyValue(k).trim();
        return t.startsWith('#') ? parseInt(t.slice(1), 16) : fb;
      };
      const V = {
        accent: readHex('--accent', 0x2c43f5),
        mint: readHex('--accent-mint', 0x12b77e),
        sun: readHex('--accent-sun', 0xf2a93b)
      };
      // 页脚恒为深底，卡面穿 Brand 奶油/墨色（与明暗主题无耦合）
      const INK = '#171512', CREAM = '#f7f5ee', MUTED = '#6f6c63';

      /* ---------------- 渲染器 / 场景 / 相机 ---------------- */
      const renderer = new T.WebGLRenderer({
        canvas, alpha: true,
        antialias: !lowPower,
        powerPreference: 'low-power'
      });
      renderer.setPixelRatio(Math.min(window.devicePixelRatio || 1, lowPower ? 1.5 : 2));
      renderer.outputColorSpace = T.SRGBColorSpace;
      renderer.toneMapping = T.ACESFilmicToneMapping;
      renderer.toneMappingExposure = 1.05;
      renderer.setClearColor(0x000000, 0);

      const scene = new T.Scene();
      const camera = new T.PerspectiveCamera(FOV, 1, 0.1, 120);

      /* ---------- 程序化环境贴图（lab3d.js 同款：Canvas 渐变 → PMREM，无外网 HDRI） ---------- */
      const makeEnv = () => {
        const c = document.createElement('canvas');
        c.width = 256; c.height = 128;
        const g = c.getContext('2d');
        const grad = g.createLinearGradient(0, 0, 0, 128);
        grad.addColorStop(0, '#ffffff');
        grad.addColorStop(0.5, '#a9b3dd');
        grad.addColorStop(1, '#141a3d');
        g.fillStyle = grad; g.fillRect(0, 0, 256, 128);
        g.globalAlpha = 0.92; g.fillStyle = '#ffffff';
        g.beginPath(); g.ellipse(56, 40, 24, 14, 0, 0, Math.PI * 2); g.fill();
        g.beginPath(); g.ellipse(206, 38, 24, 14, 0, 0, Math.PI * 2); g.fill();
        g.globalAlpha = 1;
        const tex = new T.CanvasTexture(c);
        tex.mapping = T.EquirectangularReflectionMapping;
        tex.colorSpace = T.SRGBColorSpace;
        const pmrem = new T.PMREMGenerator(renderer);
        const env = pmrem.fromEquirectangular(tex).texture;
        tex.dispose(); pmrem.dispose();
        return env;
      };
      try { scene.environment = makeEnv(); } catch (e) { /* PMREM 失败则仅靠灯光 */ }

      scene.add(new T.AmbientLight(0xffffff, 0.4));
      const key = new T.DirectionalLight(0xffffff, 2.0);
      key.position.set(3, 5, 6);
      scene.add(key);
      const rim = new T.DirectionalLight(V.mint, 0.7);
      rim.position.set(-5, 1, -4);
      scene.add(rim);
      const fill = new T.DirectionalLight(V.sun, 0.5);
      fill.position.set(0, -4, 3);
      scene.add(fill);

      const accHex = (v) => 'rgb(' + ((v >> 16) & 255) + ',' + ((v >> 8) & 255) + ',' + (v & 255) + ')';

      /* ================================================================
         品牌贴图：卡片 atlas（正面左半 / 背面右半，UV 与原版 atlas 同分布）
         挂绳织带（奶油底 · 克莱因 F8K · 重复 4 次）
         ================================================================ */
      const FONTS = {
        display: getComputedStyle(doc).getPropertyValue('--font-display') ||
          "'Clash Display','PingFang SC','Microsoft YaHei',sans-serif",
        serif: getComputedStyle(doc).getPropertyValue('--font-serif') ||
          "'Instrument Serif','Songti SC','SimSun',serif",
        mono: getComputedStyle(doc).getPropertyValue('--font-mono') ||
          "'SFMono-Regular',ui-monospace,Consolas,monospace"
      };
      const ATLAS_W = 1024, ATLAS_H = 1024;
      const FRONT_RECT = { x: 0, y: 0, w: 0.5, h: 0.755 };   // 与原版 FRONT_UV_RECT 一致
      const BACK_RECT = { x: 0.5, y: 0, w: 0.5, h: 0.757 };  // 与原版 BACK_UV_RECT 一致

      const atlasCanvas = document.createElement('canvas');
      atlasCanvas.width = ATLAS_W; atlasCanvas.height = ATLAS_H;
      const baseMap = new T.CanvasTexture(atlasCanvas);
      baseMap.flipY = false;               // glTF 约定：V 从顶往下
      baseMap.colorSpace = T.SRGBColorSpace;
      baseMap.anisotropy = 16;

      const fitFont = (g, text, family, weight, style, size, maxW) => {
        g.font = [weight, style, size + 'px', family].filter(Boolean).join(' ');
        return (g.measureText(text).width <= maxW) ? size : (size * maxW) / g.measureText(text).width;
      };

      const drawAtlas = () => {
        const g = atlasCanvas.getContext('2d');
        const fw = ATLAS_W * FRONT_RECT.w, fh = ATLAS_H * FRONT_RECT.h;

        /* 底色：奶油（也是卡片侧面/边缘色） */
        g.fillStyle = CREAM;
        g.fillRect(0, 0, ATLAS_W, ATLAS_H);

        const frame = (x0, y0, x1, y1) => {
          g.strokeStyle = 'rgba(23,21,18,.9)';
          g.lineWidth = 5;
          g.strokeRect(x0 + 24, y0 + 26, x1 - x0 - 48, y1 - y0 - 52);
          g.strokeStyle = accHex(V.mint);
          g.lineWidth = 2;
          g.strokeRect(x0 + 30, y0 + 32, x1 - x0 - 60, y1 - y0 - 64);
        };

        /* ---------- 正面（左半）：let's talk ---------- */
        frame(0, 0, fw, fh);
        g.fillStyle = INK;
        g.font = '600 64px ' + FONTS.display;
        g.textBaseline = 'alphabetic';
        g.fillText('F8K', 62, 118);
        g.font = '600 26px ' + FONTS.display;
        g.fillText('®', 62 + g.measureText('F8K').width + 6, 118);
        g.fillStyle = MUTED;
        g.font = '600 26px ' + FONTS.mono;
        g.textAlign = 'right';
        g.fillText('PORTFOLIO — 2026', fw - 62, 114);
        g.textAlign = 'left';

        g.fillStyle = accHex(V.mint);
        g.font = '600 25px ' + FONTS.mono;
        g.fillText('SAY HELLO', 62, 306);

        g.fillStyle = accHex(V.accent);
        const talk = "let's talk";
        const base = fitFont(g, talk, FONTS.serif, '', 'italic', 150, fw - 190);
        g.font = 'italic ' + base + 'px ' + FONTS.serif;
        const tw = g.measureText(talk).width;
        g.fillText(talk, (fw - tw) / 2 - 6, 512);
        g.fillStyle = accHex(V.sun);
        g.font = 'italic ' + (base * 0.62) + 'px ' + FONTS.serif;
        g.fillText('\u2197', (fw + tw) / 2 + 6, 502);

        g.fillStyle = MUTED;
        g.font = '500 27px ' + FONTS.mono;
        g.fillText('FRONT-END · CREATIVE DEVELOPER', 62, 686);

        /* ---------- 背面（右半）：联系卡 ---------- */
        const bx = ATLAS_W * BACK_RECT.x;
        frame(bx, 0, ATLAS_W, fh);
        g.fillStyle = INK;
        g.font = '600 78px ' + FONTS.display;
        g.fillText('dominicjamil', bx + 62, 130);
        g.fillStyle = accHex(V.mint);
        g.fillRect(bx + 64, 168, 190, 5);
        g.fillStyle = MUTED;
        g.font = '600 27px ' + FONTS.mono;
        g.fillText('FRONT-END / CREATIVE DEV', bx + 62, 218);

        const email = 'dominicjamil404@gmail.com';
        const es = fitFont(g, email, FONTS.mono, '600', '', 46, fw - 150);
        g.fillStyle = accHex(V.accent);
        g.font = '600 ' + es + 'px ' + FONTS.mono;
        const ew = g.measureText(email).width;
        g.fillText(email, bx + (fw - ew) / 2, 452);

        g.fillStyle = accHex(V.mint);
        const glow = 'make it glow.';
        g.font = 'italic ' + fitFont(g, glow, FONTS.serif, '', 'italic', 72, fw - 150) + 'px ' + FONTS.serif;
        const gw = g.measureText(glow).width;
        g.fillText(glow, bx + (fw - gw) / 2, 560);

        g.fillStyle = MUTED;
        g.font = '500 26px ' + FONTS.mono;
        g.fillText('GH @funny8kids', bx + 62, 690);
        g.textAlign = 'right';
        g.fillText('GMT+8 CN', bx + fw - 62, 690);
        g.textAlign = 'left';

        baseMap.needsUpdate = true;
      };
      drawAtlas();
      if (document.fonts && document.fonts.ready) {
        document.fonts.ready.then(drawAtlas).catch(() => {});
      }

      /* ---------- 挂绳织带贴图 ---------- */
      const bandCanvas = document.createElement('canvas');
      bandCanvas.width = 1024; bandCanvas.height = 160;
      const bg = bandCanvas.getContext('2d');
      bg.fillStyle = '#f6f1e4';
      bg.fillRect(0, 0, 1024, 160);
      bg.fillStyle = 'rgba(23,21,18,.05)';
      bg.fillRect(0, 0, 1024, 7); bg.fillRect(0, 153, 1024, 7);
      bg.fillStyle = accHex(V.accent);
      bg.font = '600 88px ' + FONTS.display;
      bg.textAlign = 'center';
      bg.textBaseline = 'middle';
      bg.fillText('F8K', 512, 82);
      bg.fillStyle = accHex(V.accent);
      bg.font = '600 92px ' + FONTS.display;
      bg.fillText('®', 512 + bg.measureText('F8K').width / 2 + 4, 74);
      bg.fillStyle = accHex(V.mint);
      bg.font = '44px ' + FONTS.serif;
      bg.fillText('✦', 214, 82);
      bg.fillStyle = accHex(V.sun);
      bg.fillText('✦', 810, 82);
      const bandMap = new T.CanvasTexture(bandCanvas);
      bandMap.colorSpace = T.SRGBColorSpace;
      bandMap.wrapS = bandMap.wrapT = T.RepeatWrapping;
      bandMap.repeat.set(4, 1); // 与原版 repeat [-4,1] 同密度
      bandMap.anisotropy = 16;

      /* ================================================================
         几何（card.glb 抽出：card / clip / clamp，组内定位与原版一致）
         ================================================================ */
      const fromB64 = (s, Ctor) => {
        const binStr = atob(s);
        const u = new Uint8Array(binStr.length);
        for (let i = 0; i < binStr.length; i++) u[i] = binStr.charCodeAt(i);
        return new Ctor(u.buffer);
      };
      const makeGeo = (m) => {
        const geo = new T.BufferGeometry();
        geo.setAttribute('position', new T.BufferAttribute(fromB64(m.p, Float32Array), 3));
        geo.setAttribute('normal', new T.BufferAttribute(fromB64(m.n, Float32Array), 3));
        geo.setAttribute('uv', new T.BufferAttribute(fromB64(m.u, Float32Array), 2));
        geo.setIndex(new T.BufferAttribute(fromB64(m.i, m.it === 2 ? Uint32Array : Uint16Array), 1));
        return geo;
      };

      const cardGroup = new T.Group();
      const cardMesh = new T.Mesh(makeGeo(GEO[0]), new T.MeshPhysicalMaterial({
        map: baseMap,
        roughness: 0.9, metalness: 0.8,
        clearcoat: lowPower ? 0 : 1, clearcoatRoughness: 0.15,
        envMapIntensity: 1.1,
        side: T.DoubleSide
      }));
      const makeMetal = (rough) => new T.MeshStandardMaterial({
        color: 0x090909, metalness: 1, roughness: rough,
        envMapIntensity: 2.2, side: T.DoubleSide
      });
      const clipMesh = new T.Mesh(makeGeo(GEO[1]), makeMetal(0.3));
      const clampMesh = new T.Mesh(makeGeo(GEO[2]), makeMetal(0.5));
      cardGroup.add(cardMesh, clipMesh, clampMesh);
      // 原版：RigidBody 内 group position [0,-1.2,-0.05] scale 2.25
      cardGroup.position.set(0, -1.2, -0.05);
      cardGroup.scale.setScalar(CARD_SCALE);

      const cardBody = new T.Group(); // 物理刚体位置/朝向
      cardBody.add(cardGroup);
      scene.add(cardBody);

      /* ================================================================
         系带 ribbon（MeshLine 同款：切向 × 视线 → 屏幕朝向窄带）
         ================================================================ */
      const SEG = isMobile ? 16 : 32;
      const ribbonGeo = new T.BufferGeometry();
      const ribbonPos = new Float32Array((SEG + 1) * 6);
      const ribbonUv = new Float32Array((SEG + 1) * 4);
      const ribbonIdx = [];
      for (let i = 0; i < SEG; i++) {
        const a = i * 2;
        ribbonIdx.push(a, a + 1, a + 2, a + 1, a + 3, a + 2);
      }
      for (let i = 0; i <= SEG; i++) {
        ribbonUv[i * 4] = i / SEG; ribbonUv[i * 4 + 1] = 0;
        ribbonUv[i * 4 + 2] = i / SEG; ribbonUv[i * 4 + 3] = 1;
      }
      ribbonGeo.setAttribute('position', new T.BufferAttribute(ribbonPos, 3).setUsage(T.DynamicDrawUsage));
      ribbonGeo.setAttribute('uv', new T.BufferAttribute(ribbonUv, 2).setUsage(T.DynamicDrawUsage));
      ribbonGeo.setIndex(ribbonIdx);
      const bandMat = new T.MeshBasicMaterial({ map: bandMap, side: T.DoubleSide, depthTest: false });
      const bandMesh = new T.Mesh(ribbonGeo, bandMat);
      bandMesh.renderOrder = 5;
      bandMesh.frustumCulled = false;
      scene.add(bandMesh);

      const curve = new T.CatmullRomCurve3([
        new T.Vector3(), new T.Vector3(), new T.Vector3(), new T.Vector3()
      ]);
      curve.curveType = 'chordal';

      /* ================================================================
         PBD 物理：固定环 → j1 → j2 → j3 → 卡片（bar 挂点 1.5）
         ================================================================ */
      const vUp = new T.Vector3(0, 1, 0);
      const tmpA = new T.Vector3(), tmpB = new T.Vector3(), tmpU = new T.Vector3(),
            tmpQ = new T.Quaternion(), tmpQAlign = new T.Quaternion(), tmpTwistQ = new T.Quaternion();

      const anchor = { pos: new T.Vector3(0, 2.2, 0) };
      const joints = [0, 1, 2].map((i) => ({
        pos: new T.Vector3(0.5 + i * 0.5, 2.2, 0),
        vel: new T.Vector3(),
        prevPos: null,
        lerped: new T.Vector3(0.5 + i * 0.5, 2.2, 0)
      }));
      const card = {
        pos: new T.Vector3(2, 2.2, 0.02),   // z 微偏：让开场甩动带一点 3D 出轴
        vel: new T.Vector3(),
        prevPos: null,
        quat: new T.Quaternion(),
        twist: 0, twistVel: 0,
        prevU: new T.Vector3(0, -1, 0),
        kinematic: false,
        grabOffset: new T.Vector3()
      };
      // 记下初始位置：首步速度回写就能包含开场冲量
      joints.forEach((b) => { b.prevPos = b.pos.clone(); });
      card.prevPos = card.pos.clone();

      const ropePairs = [
        [anchor.pos, joints[0].pos],
        [joints[0].pos, joints[1].pos],
        [joints[1].pos, joints[2].pos]
      ];

      const step = (dt) => {
        /* 积分（kinematic 卡片由指针驱动，不积分） */
        for (const b of joints) {
          b.vel.y += GRAVITY * dt;
          b.vel.multiplyScalar(1 / (1 + DAMP * dt));
          b.pos.addScaledVector(b.vel, dt);
        }
        const cJw = 1, cCw = card.kinematic ? 0 : 1 / C_MASS;
        if (!card.kinematic) {
          card.vel.y += GRAVITY * dt;
          card.vel.multiplyScalar(1 / (1 + DAMP * dt));
          card.pos.addScaledVector(card.vel, dt);
        }

        /* 约束投影（PBD） */
        for (let it = 0; it < ITER; it++) {
          // 绳索 max 距离（只拉不推）：anchor→j1→j2→j3；
          // 锚点视为无限质量：另一端全量回拉，绝不移动 anchor.pos
          for (const pair of ropePairs) {
            tmpA.copy(pair[1]).sub(pair[0]);
            const d = tmpA.length();
            if (d <= ROPE_LEN || d < 1e-6) continue;
            if (pair[0] === anchor.pos) {
              tmpA.multiplyScalar((d - ROPE_LEN) / d);
              pair[1].sub(tmpA);
            } else {
              tmpA.multiplyScalar((d - ROPE_LEN) / (d * 2)); // 等质量对半分
              pair[0].add(tmpA); pair[1].sub(tmpA);
            }
          }
          // 卡片挂点 bar：|card.pos − j3| = HANG_LEN（双向、按质量配分）
          tmpB.copy(card.pos).sub(joints[2].pos);
          const bd = tmpB.length();
          if (bd > 1e-6) {
            const diff = bd - HANG_LEN;
            if (Math.abs(diff) > 1e-6) {
              tmpB.multiplyScalar(diff / (bd * (cJw + cCw)));
              joints[2].pos.addScaledVector(tmpB, cJw);
              card.pos.addScaledVector(tmpB, -cCw);
            }
          }
        }

        /* 速度回写（PBD：速度 = 位移/dt） */
        for (const b of joints) {
          b.vel.copy(b.pos).sub(b.prevPos).divideScalar(dt);
          b.prevPos.copy(b.pos);
        }
        if (!card.kinematic) {
          card.vel.copy(card.pos).sub(card.prevPos).divideScalar(dt);
        }
        card.prevPos.copy(card.pos);

        /* ---------- 卡片朝向：挂点方向对齐 (0,1,0) + 扭摆 ---------- */
        tmpU.copy(joints[2].pos).sub(card.pos);
        if (tmpU.lengthSq() < 1e-8) tmpU.copy(card.prevU);
        tmpU.normalize();
        // 摆动越猛，卡面绕挂轴翻得越欢（真实挂绳的 waddle）
        const swingAxis = tmpB.copy(card.prevU).cross(tmpU);
        const swing = swingAxis.length(); // ≈ |sin Δθ|
        if (swing > 1e-5) {
          card.twistVel += (swingAxis.z >= 0 ? 1 : -1) * swing * SWING_TWIST;
        }
        card.twistVel = (card.twistVel - card.twist * 6 * dt) / (1 + DAMP * dt);
        card.twist += card.twistVel * dt;
        card.prevU.copy(tmpU);
        tmpQAlign.setFromUnitVectors(vUp, tmpU);
        tmpTwistQ.setFromAxisAngle(vUp, card.twist);
        card.quat.copy(tmpQAlign).multiply(tmpTwistQ);
      };

      /* ---------- 拖拽（与原版 mapping 一致：z=0 指针平面） ---------- */
      const raycaster = new T.Raycaster();
      const ndc = new T.Vector2();
      const dragPlane = new T.Plane(new T.Vector3(0, 0, 1), 0);
      const hitPoint = new T.Vector3();
      const drag = { active: false, pointerId: -1 };

      const setNdc = (e) => {
        const r = canvas.getBoundingClientRect();
        ndc.x = ((e.clientX - r.left) / r.width) * 2 - 1;
        ndc.y = -((e.clientY - r.top) / r.height) * 2 + 1;
      };
      const planePoint = () => {
        raycaster.setFromCamera(ndc, camera);
        return raycaster.ray.intersectPlane(dragPlane, hitPoint);
      };

      canvas.addEventListener('pointerdown', (e) => {
        setNdc(e);
        raycaster.setFromCamera(ndc, camera);
        if (!raycaster.intersectObject(cardGroup, true).length) return;
        canvas.setPointerCapture(e.pointerId);
        drag.active = true; drag.pointerId = e.pointerId;
        planePoint();
        card.grabOffset.copy(card.pos).sub(hitPoint);
        card.kinematic = true;
        stage.classList.add('is-dragging');
        e.preventDefault();
      });
      canvas.addEventListener('pointermove', (e) => {
        if (!drag.active || e.pointerId !== drag.pointerId) return;
        setNdc(e);
        if (planePoint()) card.pos.copy(hitPoint).add(card.grabOffset);
      });
      const endDrag = (e) => {
        if (!drag.active || (e && e.pointerId !== drag.pointerId)) return;
        drag.active = false;
        card.kinematic = false;
        card.vel.copy(cardStepVel); // 继承拖拽速度（抛掷惯性）
        stage.classList.remove('is-dragging');
      };
      canvas.addEventListener('pointerup', endDrag);
      canvas.addEventListener('pointercancel', endDrag);

      /* ================================================================
         循环：静止 30fps 隔帧 / 拖拽 60fps；离屏与后台暂停
         ================================================================ */
      let running = false, inView = false, rafId = 0, frame = 0,
          accumulator = 0, lastT = 0;
      const cardStepVel = new T.Vector3();

      const renderFrame = (t) => {
        /* 物理固定步长累积（1/120s × 4/步 在 30fps 下刚好一帧） */
        const fdt = lastT ? (t - lastT) / 1000 : 1 / 60;
        lastT = t;
        accumulator += Math.min(0.05, fdt);
        let guard = 0;
        while (accumulator >= STEP && guard++ < 8) {
          const pre = tmpA.copy(card.pos).sub(card.prevPos); // 拖拽速度（指针位移）
          step(STEP);
          if (card.kinematic && pre.lengthSq() > 1e-12) cardStepVel.copy(pre).divideScalar(STEP);
          accumulator -= STEP;
        }
        if (!card.kinematic) cardStepVel.copy(card.vel); // 松手时继承

        /* 绳结平滑（原版 lerped：按偏离距离自适应追赶速度，minSpeed 0 / maxSpeed 50） */
        for (let i = 0; i < 2; i++) {
          const j = joints[i];
          const clamped = Math.max(0.1, Math.min(1, j.lerped.distanceTo(j.pos)));
          j.lerped.lerp(j.pos, Math.min(1, fdt * clamped * 50));
        }

        /* 系带曲线与 ribbon */
        curve.points[0].copy(joints[2].pos);
        curve.points[1].copy(joints[1].lerped);
        curve.points[2].copy(joints[0].lerped);
        curve.points[3].copy(anchor.pos);
        const pts = curve.getPoints(SEG);
        for (let i = 0; i <= SEG; i++) {
          const p = pts[i];
          tmpA.copy(pts[Math.min(i + 1, SEG)]).sub(pts[Math.max(i - 1, 0)]);
          if (tmpA.lengthSq() < 1e-9) tmpA.set(0, -1, 0);
          tmpA.normalize();
          tmpB.copy(p).sub(camera.position).normalize();
          tmpB.cross(tmpA);
          if (tmpB.lengthSq() < 1e-6) tmpB.set(0, 0, 1); else tmpB.normalize();
          const hw = BAND_WIDTH / 2;
          ribbonPos[i * 6] = p.x + tmpB.x * hw; ribbonPos[i * 6 + 1] = p.y + tmpB.y * hw; ribbonPos[i * 6 + 2] = p.z + tmpB.z * hw;
          ribbonPos[i * 6 + 3] = p.x - tmpB.x * hw; ribbonPos[i * 6 + 4] = p.y - tmpB.y * hw; ribbonPos[i * 6 + 5] = p.z - tmpB.z * hw;
        }
        ribbonGeo.attributes.position.needsUpdate = true;

        cardBody.position.copy(card.pos);
        cardBody.quaternion.copy(card.quat);

        renderer.render(scene, camera);
        if (!canvas.classList.contains('is-on')) canvas.classList.add('is-on');
      };

      const tick = (t) => {
        if (!running) return;
        if ((frame++ & 1) === 0 || drag.active) renderFrame(t);
        rafId = requestAnimationFrame(tick);
      };
      const setRunning = (on) => {
        const want = on && inView && !document.hidden;
        if (want === running) return;
        running = want;
        lastT = 0; accumulator = 0;
        if (running) rafId = requestAnimationFrame(tick);
        else cancelAnimationFrame(rafId);
      };

      canvas.addEventListener('webglcontextlost', (e) => {
        e.preventDefault();
        running = false;
        cancelAnimationFrame(rafId);
        canvas.classList.remove('is-on');
      }, false);
      canvas.addEventListener('webglcontextrestored', () => {
        resize();
        frame = 0;
        setRunning(true);
      }, false);

      /* ---------- 取景：fov 20，按舞台宽高比自适应距离 ---------- */
      const fit = () => {
        const w = canvas.clientWidth || 300, h = canvas.clientHeight || 300;
        const tanHalf = Math.tan((FOV / 2) * Math.PI / 180);
        camera.position.z = Math.max(FIT_H / tanHalf, FIT_W / (tanHalf * Math.max(0.1, w / h))) + 1.2;
        camera.position.y = CENTER_Y;
        camera.lookAt(0, CENTER_Y, 0);
        camera.updateProjectionMatrix();
      };
      const resize = () => {
        const w = canvas.clientWidth || 300, h = canvas.clientHeight || 300;
        renderer.setSize(w, h, false);
        camera.aspect = w / h;
        fit();
      };
      resize();
      window.addEventListener('resize', () => {
        clearTimeout(resize.t);
        resize.t = setTimeout(resize, 200);
      });

      /* ---------- 视口/后台进出控制 ---------- */
      new IntersectionObserver((en) => {
        inView = en[0].isIntersecting;
        setRunning(true);
      }, { rootMargin: '160px' }).observe(canvas);
      document.addEventListener('visibilitychange', () => setRunning(true));

      // 开场冲量：系上后自然的左右摇晃
      joints[0].vel.set(-1.4, 0, 0.1);
      card.vel.set(-1.2, -1.0, 0.12);

      window.__f8kLanyard = true; // 调试验证标记
    } catch (e) { /* WebGL 不可用则静默跳过 */ }
  }
})();
